svg.script:
//!export-start
let _pb_running = false;
let _pn_speed = 0;
let _pb_vertical = false;
let _ps_labelDirection = 'down';
let _pb_alarm = false;
let _pb_auto = false;
let _pb_locked = false;
let _pb_duty = false;
let _pb_alarmOff = false;
let _ps_tag = '';
let _pb_command = false;
//!export-end

var __busyUntil = 0;

function toBool(v) {
    if (v === true || v === 1) return true;
    var s = String(v).toLowerCase();
    return s === 'true' || s === '1' || s === 'on';
}

function toNum(v) {
    if (v === true || v === 'true') return 1;
    if (v === false || v === 'false') return 0;
    var n = parseFloat(v);
    return isNaN(n) ? 0 : n;
}

function apply() {
    var preview = document.getElementById('ob_preview');
    if (preview && preview.parentNode) { preview.parentNode.removeChild(preview); }
    var el = document.getElementById('ob_el');
    if (!el) return;
    el.on = toBool(_pb_running);
    el.speedInPercent = toNum(_pn_speed);
    el.vertical = toBool(_pb_vertical);
    el.labelDirection = String(_ps_labelDirection);
    el.alert = toBool(_pb_alarm);
    el.badgeAuto = toBool(_pb_auto);
    el.badgeCommandLocked = toBool(_pb_locked);
    el.badgeDuty = toBool(_pb_duty);
    el.badgeAlertOff = toBool(_pb_alarmOff);
    el.tag = String(_ps_tag);
    el.hasIdTag = String(_ps_tag).length > 0;
}

function putValue(id, value) {
    if (id === '_pb_running') { _pb_running = toBool(value); }
    if (id === '_pn_speed') { _pn_speed = toNum(value); }
    if (id === '_pb_vertical') { _pb_vertical = toBool(value); }
    if (id === '_ps_labelDirection') { _ps_labelDirection = String(value); }
    if (id === '_pb_alarm') { _pb_alarm = toBool(value); }
    if (id === '_pb_auto') { _pb_auto = toBool(value); }
    if (id === '_pb_locked') { _pb_locked = toBool(value); }
    if (id === '_pb_duty') { _pb_duty = toBool(value); }
    if (id === '_pb_alarmOff') { _pb_alarmOff = toBool(value); }
    if (id === '_ps_tag') { _ps_tag = String(value); }
    if (id === '_pb_command') { _pb_command = toBool(value); }
    apply();
}

function postValue(id, value) {
    // replaced at runtime: writes value to the tag bound to "id"
}

function onCommandClick() {
    _pb_command = !toBool(_pb_running);
    postValue('_pb_command', _pb_command ? 1 : 0);
}

(function () {
    var el = document.getElementById('ob_el');
    if (el) { el.addEventListener('click', onCommandClick); }
})();

apply();
